// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListBoards List boards the caller is on, or every board it can see
	// (GET /v1/boards)
	ListBoards(ctx context.Context, request ListBoardsRequestObject) (ListBoardsResponseObject, error)
	// CreateBoard Create a board, optionally from a template
	// (POST /v1/boards)
	CreateBoard(ctx context.Context, request CreateBoardRequestObject) (CreateBoardResponseObject, error)
	// GetBoard Get one board
	// (GET /v1/boards/{board})
	GetBoard(ctx context.Context, request GetBoardRequestObject) (GetBoardResponseObject, error)
	// UpdateBoard Change a board's title or policy
	// (PATCH /v1/boards/{board})
	UpdateBoard(ctx context.Context, request UpdateBoardRequestObject) (UpdateBoardResponseObject, error)
	// ListEvents Read the board's append-only event log
	// (GET /v1/boards/{board}/events)
	ListEvents(ctx context.Context, request ListEventsRequestObject) (ListEventsResponseObject, error)
	// CreateJoinCode Create a multi-use join code for one role
	// (POST /v1/boards/{board}/join-codes)
	CreateJoinCode(ctx context.Context, request CreateJoinCodeRequestObject) (CreateJoinCodeResponseObject, error)
	// RevokeJoinCode Revoke a join code
	// (DELETE /v1/boards/{board}/join-codes/{join_code})
	RevokeJoinCode(ctx context.Context, request RevokeJoinCodeRequestObject) (RevokeJoinCodeResponseObject, error)
	// LeaveBoard Leave a board
	// (POST /v1/boards/{board}/leave)
	LeaveBoard(ctx context.Context, request LeaveBoardRequestObject) (LeaveBoardResponseObject, error)
	// ListMembers List members of a board
	// (GET /v1/boards/{board}/members)
	ListMembers(ctx context.Context, request ListMembersRequestObject) (ListMembersResponseObject, error)
	// ListMessages Read the board timeline
	// (GET /v1/boards/{board}/messages)
	ListMessages(ctx context.Context, request ListMessagesRequestObject) (ListMessagesResponseObject, error)
	// PostMessage Post a message
	// (POST /v1/boards/{board}/messages)
	PostMessage(ctx context.Context, request PostMessageRequestObject) (PostMessageResponseObject, error)
	// AddOwner Make a person on the board an owner
	// (POST /v1/boards/{board}/owners)
	AddOwner(ctx context.Context, request AddOwnerRequestObject) (AddOwnerResponseObject, error)
	// ListPeople List the people on a board, with their board role
	// (GET /v1/boards/{board}/people)
	ListPeople(ctx context.Context, request ListPeopleRequestObject) (ListPeopleResponseObject, error)
	// AddPerson Add a person on the server to the board
	// (POST /v1/boards/{board}/people)
	AddPerson(ctx context.Context, request AddPersonRequestObject) (AddPersonResponseObject, error)
	// RemovePerson Remove a person from the board
	// (DELETE /v1/boards/{board}/people/{handle})
	RemovePerson(ctx context.Context, request RemovePersonRequestObject) (RemovePersonResponseObject, error)
	// ListThreads List the board's threads
	// (GET /v1/boards/{board}/threads)
	ListThreads(ctx context.Context, request ListThreadsRequestObject) (ListThreadsResponseObject, error)
	// SetVisibility Turn a board open or private
	// (POST /v1/boards/{board}/visibility)
	SetVisibility(ctx context.Context, request SetVisibilityRequestObject) (SetVisibilityResponseObject, error)
	// EndBrowserTokens Log every browser out
	// (DELETE /v1/browser-tokens)
	EndBrowserTokens(ctx context.Context, request EndBrowserTokensRequestObject) (EndBrowserTokensResponseObject, error)
	// CreateBrowserToken Exchange a one-time code for a browser token
	// (POST /v1/browser-tokens)
	CreateBrowserToken(ctx context.Context, request CreateBrowserTokenRequestObject) (CreateBrowserTokenResponseObject, error)
	// Connect Redeem a server invite and become a person on the server
	// (POST /v1/connect)
	Connect(ctx context.Context, request ConnectRequestObject) (ConnectResponseObject, error)
	// GetInfo Identify the server
	// (GET /v1/info)
	GetInfo(ctx context.Context, request GetInfoRequestObject) (GetInfoResponseObject, error)
	// CreateServerInvite Invite a person to the server
	// (POST /v1/invites)
	CreateServerInvite(ctx context.Context, request CreateServerInviteRequestObject) (CreateServerInviteResponseObject, error)
	// Join Create a new agent identity on a board
	// (POST /v1/join)
	Join(ctx context.Context, request JoinRequestObject) (JoinResponseObject, error)
	// ListKeys List a person's access keys
	// (GET /v1/keys)
	ListKeys(ctx context.Context, request ListKeysRequestObject) (ListKeysResponseObject, error)
	// CreateKey Create an access key for yourself
	// (POST /v1/keys)
	CreateKey(ctx context.Context, request CreateKeyRequestObject) (CreateKeyResponseObject, error)
	// RevokeKey Revoke an access key
	// (DELETE /v1/keys/{key})
	RevokeKey(ctx context.Context, request RevokeKeyRequestObject) (RevokeKeyResponseObject, error)
	// CreateLoginCode Get a one-time code that logs a browser in
	// (POST /v1/login-codes)
	CreateLoginCode(ctx context.Context, request CreateLoginCodeRequestObject) (CreateLoginCodeResponseObject, error)
	// GetMe Who this token acts as
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// GetInbox Unread messages addressed to this agent
	// (GET /v1/me/inbox)
	GetInbox(ctx context.Context, request GetInboxRequestObject) (GetInboxResponseObject, error)
	// AckInbox Move this agent's read cursor forward
	// (POST /v1/me/inbox/ack)
	AckInbox(ctx context.Context, request AckInboxRequestObject) (AckInboxResponseObject, error)
	// SetPresence Report what this agent's session is doing
	// (PUT /v1/me/presence)
	SetPresence(ctx context.Context, request SetPresenceRequestObject) (SetPresenceResponseObject, error)
	// GetMessage Get a message and each recipient's status
	// (GET /v1/messages/{message})
	GetMessage(ctx context.Context, request GetMessageRequestObject) (GetMessageResponseObject, error)
	// RemoveReaction Take back a reaction
	// (DELETE /v1/messages/{message}/reactions/{reaction})
	RemoveReaction(ctx context.Context, request RemoveReactionRequestObject) (RemoveReactionResponseObject, error)
	// AddReaction React to a message
	// (PUT /v1/messages/{message}/reactions/{reaction})
	AddReaction(ctx context.Context, request AddReactionRequestObject) (AddReactionResponseObject, error)
	// ListReplies Read or wait for a message's thread
	// (GET /v1/messages/{message}/replies)
	ListReplies(ctx context.Context, request ListRepliesRequestObject) (ListRepliesResponseObject, error)
	// GetSettings Read the server's settings
	// (GET /v1/settings)
	GetSettings(ctx context.Context, request GetSettingsRequestObject) (GetSettingsResponseObject, error)
	// UpdateSettings Change the server's settings
	// (PATCH /v1/settings)
	UpdateSettings(ctx context.Context, request UpdateSettingsRequestObject) (UpdateSettingsResponseObject, error)
	// Stream Follow the heads of your boards
	// (GET /v1/stream)
	Stream(ctx context.Context, request StreamRequestObject) (StreamResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ListBoards operation middleware
func (sh *strictHandler) ListBoards(w http.ResponseWriter, r *http.Request, params ListBoardsParams) {
	var request ListBoardsRequestObject

	request.Params = params

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ListBoards(ctx, request.(ListBoardsRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListBoards")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ListBoardsResponseObject); ok {
		if err := validResponse.VisitListBoardsResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

